# Import packages
from numpy import exp, pi, sqrt

# Define each QHO wave function

def Psi_QHO(i, r, m, w):
    # Functions obtained from scipy.physics.qho_1d
    hbar = 1 #atomic units
    if i==0:
        return (m*w)**(1/4)*exp(-m*r**2*w/(2*hbar))/(hbar**(1/4)*pi**(1/4))
    elif i==1:
        return sqrt(2)*r*(m*w)**(3/4)*exp(-m*r**2*w/(2*hbar))/(hbar**(3/4)*pi**(1/4))
    elif i==2:
        return sqrt(2)*(m*w)**(1/4)*(4*m*r**2*w/hbar - 2)*exp(-m*r**2*w/(2*hbar))/(4*hbar**(1/4)*pi**(1/4))
